import openpyxl
wb = openpyxl.load_workbook("/tmp/world/filesystem/mmc3.xlsx", data_only=True); ws = wb.active
donor = {r: ws.cell(r,1).value for r in range(2, ws.max_row+1)}
hdr = {c.column_letter: c.value for c in ws[1]}
for mr in sorted(ws.merged_cells.ranges, key=lambda m:(m.min_col, m.min_row)):
    ds = {str(donor[r]) for r in range(mr.min_row, mr.max_row+1)}
    if len(ds)>1:
        print("CROSS-DONOR MERGE:", mr.coord, "column:", hdr[mr.coord[0:2].rstrip('0123456789')] if mr.coord[1].isalpha() else hdr[mr.coord[0]], "donors:", ds, "value:", repr(ws.cell(mr.min_row, mr.min_col).value))
# Donor-level fields present on non-first blocks (unmerged)
import collections
rows_by_donor = collections.OrderedDict()
for r in range(2, ws.max_row+1):
    if donor[r] is None: continue
    rows_by_donor.setdefault(str(donor[r]), []).append(r)
merged_cells = set()
for mr in ws.merged_cells.ranges:
    for r in range(mr.min_row, mr.max_row+1):
        for c in range(mr.min_col, mr.max_col+1):
            if (r,c)!=(mr.min_row, mr.min_col): merged_cells.add((r,c))
for col in ["F","G","H","I","J","K","AA"]:
    ci = openpyxl.utils.column_index_from_string(col)
    for d, rs in rows_by_donor.items():
        first = rs[0]
        for r in rs[1:]:
            v = ws.cell(r, ci).value
            if v is not None and (r,ci) not in merged_cells:
                print(f"donor {d}: column {col} ({hdr[col]!r}) has a value on non-first block row {r}: {str(v)[:40]!r}; first-block value: {str(ws.cell(first,ci).value)[:40]!r}")
print("blocks per donor:", {d: len(rs) for d,rs in rows_by_donor.items()})
EOF
